(317569200430252032, 317569200321200128, 317569200094707712, 'mri', '/images/mri_20260308.dcm', '/thumbs/mri_20260308_thumb.jpg', 'MRI20260308001', '上海市康复医院影像科', '赵主任', '2026-03-08', '左侧基底节区陈旧性脑梗死', '左侧基底节区可见片状长T1长T2信号影，FLAIR呈低信号伴周围胶质增生，大小约2.0cm×1.5cm；右侧放射冠区可见散在斑点状FLAIR高信号，Fazekas 2级', '脑白质疏松（Fazekas 2级）', NOW()),
(317569200434446336, 317569200333783040, 317569200119873536, 'ecg', '/images/ecg_20260315.pdf', '/thumbs/ecg_20260315_thumb.jpg', 'ECG20260315002', '上海市社区卫生服务中心心电室', '陈技师', '2026-03-15', '窦性心律，ST-T改变', '心率78bpm，PR间期160ms，QRS时限95ms，QTc 430ms，V4-V6导联ST段压低0.05-0.08mV伴T波低平/倒置', 'ST-T改变（V4-V6导联）', NOW()),
(317569200442834944, NULL, 317569200073736192, 'ct', '/images/ct_20260110.dcm', '/thumbs/ct_20260110_thumb.jpg', 'CT20260110001', '上海市徐汇区中心医院影像科', '孙主任', '2026-01-10', '冠状动脉钙化积分增高', '冠状动脉CTA显示：左前降支中段钙化斑块伴管腔中度狭窄（约50-60%），回旋支近段轻度狭窄（约30%），右冠状动脉未见明显狭窄', '冠脉钙化积分：Agatston评分 380', NOW()),
(317569200451223552, NULL, 317569200086319104, 'mri', '/images/mri_20251201.dcm', '/thumbs/mri_20251201_thumb.jpg', 'MRI20251201001', '上海市长宁区中心医院影像科', '钱主任', '2025-12-01', '脑萎缩伴白质病变', '头颅MRI平扫：双侧大脑半球脑沟增宽加深，侧脑室轻度扩大，符合老年性脑萎缩改变；双侧侧脑室周围可见对称性T2/FLAIR高信号，符合脑小血管病白质病变表现', '脑萎缩（轻度），脑白质高信号（Fazekas 2级）', NOW());
INSERT INTO smart_assessment (id, collection_id, elder_id, assessment_type, assessment_items, total_score, score_level, assessment_result, recommendations, assessor, assessment_device, assessment_time, create_time) VALUES
(317569200455417856, 317569200300228608, 317569200069541888, 'cognitive', '{"mmse":24, "moca":22, "digit_span_forward":7, "digit_span_backward":4, "verbal_fluency":12, "clock_drawing":3}', 24, 'mild', '轻度认知障碍，以记忆力和执行功能下降为主，语言功能相对保留较好', '推荐使用"脑力锻炼"APP每日训练20分钟，重点训练工作记忆和认知灵活性模块', '张医生', '智能评估一体机（型号：CogAssess-3000）', '2026-03-05 10:00:00', NOW()),
(317569200463806464, 317569200321200128, 317569200094707712, 'cognitive', '{"moca":20, "trail_making_a":68, "trail_making_b":145, "stroop_interference":0.45, "digit_symbol":35}', 20, 'moderate', '中度认知障碍，信息处理速度显著减慢，执行功能受损明显，符合脑梗后认知损害特点', '建议认知康复软件训练+作业治疗师一对一指导，频率从每周3次开始', '李医生', '智能评估一体机（型号：CogAssess-3000）', '2026-03-10 14:00:00', NOW()),
(317569200468000768, 317569200312811520, 317569200086319104, 'motor', '{"updrs_iii":38, "timed_up_and_go":22, "gait_speed":0.6, "berg_balance":35, "five_times_sit_to_stand":28}', 38, 'severe', '运动功能障碍严重（UPDRS-III 38分），平衡功能差（Berg 35分），步速缓慢（0.6m/s），TUG时间延长（22s）', '建议防跌倒家居评估，考虑使用助行器，增加平衡训练频率至每周5次', '王医生', '运动功能评估系统（型号：MotoEval-200）', '2026-03-15 09:30:00', NOW()),
(317569200476389376, NULL, 317569200107290624, 'vital', '{"fev1":1.2, "fev1_percent":52, "fvc":2.1, "fev1_fvc":58, "spo2":93, "mmrc":2, "cat_score":18}', NULL, 'moderate', '中度COPD（GOLD 2级），肺功能中度下降，CAT评分18分提示症状负担较重，静息SpO2偏低', '持续家庭氧疗（2L/min，每日≥15h），肺康复计划需结合认知训练同步进行', '王医生', '便携式肺功能检测仪（型号：SpiroCare-P100）', '2026-03-18 11:00:00', NOW());
INSERT INTO health_questionnaire (id, collection_id, elder_id, questionnaire_type, questions, answers, risk_factors, summary, surveyor, survey_time, create_time) VALUES
(317569200480583680, NULL, 317569200069541888, 'lifestyle', '["您每周运动次数？", "您是否吸烟？", "您每天的睡眠时间？", "您是否有社交活动？", "您是否饮酒？", "您每天蔬菜水果摄入量？"]', '["3-4次", "已戒烟10年", "6-7小时", "每周参加社区太极班", "偶尔少量", "约300g/天"]', '运动量不足（<5次/周），蔬菜摄入未达标（<500g/天）', '生活方式总体健康，已戒烟，社交活跃，需增加运动频率和蔬菜摄入', '张医生', '2026-03-01 09:00:00', NOW()),
(317569200488972288, NULL, 317569200073736192, 'medical', '["您目前服用哪些药物？", "是否有药物不良反应？", "您最近一周有无胸痛？", "您有无气短加重？", "您体重变化情况？", "您有无水肿？"]', '["阿司匹林100mg，氯吡格雷75mg，阿托伐他汀20mg，美托洛尔25mg，多奈哌齐5mg", "偶有胃部不适", "无胸痛发作", "上3楼时轻度气短", "近3个月下降2kg", "双下肢轻度凹陷性水肿"]', '冠心病+心衰风险（双下肢水肿+体重下降），多重用药（5种）', '需关注心功能恶化迹象，药物间相互作用需药师评估，建议营养干预防止继续体重下降', '李医生', '2026-02-28 14:00:00', NOW()),
(317569200493166592, NULL, 317569200098902016, 'symptom', '["您最近有无记忆力下降？", "您有无失眠问题？", "您有无关节疼痛？", "您有无头晕/眩晕？", "您有无听力下降？", "您有无情绪低落？"]', '["偶尔忘记物品放置位置", "入睡困难约30min，每周2-3次", "右膝关节晨起僵硬，活动后缓解", "体位改变时有轻度头晕", "右耳听力下降，左耳正常", "偶尔感到孤独，女儿每周来看一次"]', '失眠（入睡困难），听力下降（右侧），轻度抑郁风险（孤独感）', '建议听力检查，考虑佩戴助听器；失眠可通过睡前放松训练改善；建议增加社区活动频次缓解孤独感', '张医生', '2026-03-12 10:30:00', NOW()),
(317569200501555200, NULL, 317569200111484928, 'family', '["您父母是否健在？", "您的兄弟姐妹健康状况如何？", "您子女多久来看您一次？", "您目前主要照护者是谁？", "您居住环境有无安全隐患？", "您家庭经济状况如何？"]', '["父亲已故（肺癌75岁），母亲已故（自然死亡92岁）", "1兄健在（85岁，体健），1妹健在（82岁，高血压）", "儿子每周来2-3次，女儿在外地每月视频通话", "日常生活自理，儿子负责购物和就医陪同", "卫生间无扶手，地面为光滑瓷砖，夜间照明不足", "退休金+儿女支持，基本满足生活需求"]', '居家安全隐患（卫浴无扶手+光滑地面+照明不足），主要照护者非全天候', '建议安装卫生间扶手和防滑垫，增加夜灯照明，预防跌倒风险', '张医生', '2026-03-26 09:00:00', NOW());
