-- ============================================
-- 测试数据填充脚本（约50行，不含 sys_user 表）
-- 执行前会清空所有非 user 表数据
-- ============================================
USE cognitive_health;

SET FOREIGN_KEY_CHECKS = 0;

TRUNCATE TABLE health_questionnaire;
TRUNCATE TABLE smart_assessment;
TRUNCATE TABLE image_report;
TRUNCATE TABLE intervention_execution;
TRUNCATE TABLE intervention_plan;
TRUNCATE TABLE cognitive_assessment;
TRUNCATE TABLE health_data_collection;
TRUNCATE TABLE risk_warning;
TRUNCATE TABLE sys_dict;
TRUNCATE TABLE elder_health_record;

-- collection_id 允许为空（部分记录不关联采集单）
ALTER TABLE image_report MODIFY collection_id BIGINT NULL;
ALTER TABLE smart_assessment MODIFY collection_id BIGINT NULL;
ALTER TABLE health_questionnaire MODIFY collection_id BIGINT NULL;

SET FOREIGN_KEY_CHECKS = 1;

