-- ============================================
-- 完成提示
-- ============================================
SELECT '数据填充完成！共填充 ' || COUNT(*) || ' 行数据（不含sys_user）' AS result FROM (
    SELECT 'elder_health_record' AS tbl, COUNT(*) AS cnt FROM elder_health_record
    UNION ALL SELECT 'cognitive_assessment', COUNT(*) FROM cognitive_assessment
    UNION ALL SELECT 'intervention_plan', COUNT(*) FROM intervention_plan
    UNION ALL SELECT 'intervention_execution', COUNT(*) FROM intervention_execution
    UNION ALL SELECT 'health_data_collection', COUNT(*) FROM health_data_collection
    UNION ALL SELECT 'risk_warning', COUNT(*) FROM risk_warning
    UNION ALL SELECT 'sys_dict', COUNT(*) FROM sys_dict
    UNION ALL SELECT 'image_report', COUNT(*) FROM image_report
    UNION ALL SELECT 'smart_assessment', COUNT(*) FROM smart_assessment
    UNION ALL SELECT 'health_questionnaire', COUNT(*) FROM health_questionnaire
) t;
